function config({ owner, repo, path }) {
  for (const [k, v] of Object.entries({ owner, repo, path }))
    if (typeof v !== "string" || !v.trim() || v.startsWith("YOUR_"))
      throw Error("Configure GitHub " + k);
  if (
    path.startsWith("/") ||
    path.endsWith("/") ||
    path.split("/").some((x) => !x || x === "." || x === "..")
  )
    throw Error("Invalid existing directory");
  return { owner, repo, path };
}

return [
  {
    json: config({
      owner: "YOUR_GITHUB_OWNER",
      repo: "YOUR_GITHUB_REPO",
      path: "YOUR_EXISTING_BACKUP_DIRECTORY",
    }),
  },
];

const items = $input.all().flatMap((x) => {
  const v = x.json;
  if (!Object.keys(v).length) return [];
  if (typeof v.id !== "string" || !v.id) throw Error("Invalid workflow");
  return [v];
});
return [{ json: { items } }];

function plan({ state, entries, owner, repo, path }) {
  for (const [k, v] of Object.entries({ owner, repo, path }))
    if (typeof v !== "string" || !v.trim() || v.startsWith("YOUR_"))
      throw Error("Configure GitHub " + k);
  if (!Array.isArray(state?.items) || !Array.isArray(entries))
    throw Error("Invalid workflow or directory list");
  if (entries.length >= 1000) throw Error("Directory may exceed the GitHub listing limit");
  if (
    path.startsWith("/") ||
    path.endsWith("/") ||
    path.split("/").some((x) => !x || x === "." || x === "..")
  )
    throw Error("Invalid existing directory");
  const seen = new Set(),
    items = [];
  for (const w of state.items) {
    if (
      typeof w?.id !== "string" ||
      !w.id ||
      typeof w.name !== "string" ||
      !w.name ||
      /[\/\\\u0000-\u001f]/.test(w.name) ||
      w.name === "." ||
      w.name === ".."
    )
      throw Error("Workflow name cannot be used as a file name");
    const name = w.name + ".json";
    if (seen.has(name)) throw Error("Workflow names would collide");
    seen.add(name);
    const matches = entries.filter((e) => e.name === name);
    if (
      matches.length > 1 ||
      matches.some((e) => e.type !== "file" || typeof e.sha !== "string" || !e.sha)
    )
      throw Error("Invalid GitHub directory entry");
    items.push({ workflowId: w.id, name, path: path + "/" + name, exists: matches.length === 1 });
  }
  return { items };
}

const c = $("Choose the backup repository").first().json;
const entries = $input.all().flatMap((x) => (Object.keys(x.json).length ? [x.json] : []));
return plan({ state: $("Collect workflow list").first().json, entries, ...c }).items.map(
  (json) => ({ json }),
);

const w = $input.first().json,
  item = $("Back up one workflow at a time").item.json;
if (
  w.id !== item.workflowId ||
  w.name + ".json" !== item.name ||
  !Array.isArray(w.nodes) ||
  !w.connections ||
  typeof w.connections !== "object"
)
  throw Error("Workflow changed during backup");
return [{ json: w, pairedItem: { item: 0 } }];

const item = $("Back up one workflow at a time").item.json,
  w = $("Read the n8n workflow").item.json,
  file = $input.first().json;
if (
  w.id !== item.workflowId ||
  w.name + ".json" !== item.name ||
  file.type !== "file" ||
  file.path !== item.path ||
  typeof file.sha !== "string" ||
  !file.sha ||
  typeof file.content !== "string"
)
  throw Error("Invalid backup or workflow");
let old;
try {
  old = JSON.parse(Buffer.from(file.content, "base64").toString("utf8"));
} catch {
  throw Error("Existing backup is not JSON");
}
if (!old || typeof old !== "object" || Array.isArray(old))
  throw Error("Existing backup is not a workflow");
const order = (x) =>
  Object.fromEntries(
    Object.keys(x)
      .sort()
      .map((k) => [k, x[k]]),
  );
return [
  {
    json: { changed: JSON.stringify(order(old)) !== JSON.stringify(order(w)) },
    pairedItem: { item: 0 },
  },
];
